def find_min_arrow_shots(points):
    if not points:
        return 0

    sorted_points = sorted(points, key=lambda p: p[1])
    arrows = 1
    arrow_pos = sorted_points[0][1]

    for start, end in sorted_points[1:]:
        if start > arrow_pos:
            arrows += 1
            arrow_pos = end

    return arrows

